const $=s=>document.querySelector(s),canvas=$('#revealCanvas'),ctx=canvas.getContext('2d'),mask=document.createElement('canvas'),mctx=mask.getContext('2d'),photo=document.createElement('canvas'),pctx=photo.getContext('2d');
let model=null,modelPromise=null,item=null,lastId=null,image=new Image(),ready=false,drawing=false,points=[],coverage=0,lastAnalyze=0,analysisTimer=null,analyzing=false,pendingAnalysis=false,trace=[],predictions={},finalPrediction=null,sessionId='',archiveFilter='all';
function norm(s=''){return s.trim().toLowerCase().replaceAll('_',' ')}
function show(id){['intro','experiment','result','evidence'].forEach(x=>$('#'+x).classList.toggle('active',x===id));scrollTo(0,0)}
function setupHome(){const home=$('#intro'),f=$('#frostLayer'),c=$('#revealCursor'),move=e=>{const b=home.getBoundingClientRect(),x=e.clientX-b.left,y=e.clientY-b.top;f.style.setProperty('--x',x+'px');f.style.setProperty('--y',y+'px');f.style.setProperty('--spot','185px');c.style.left=x+'px';c.style.top=y+'px';home.classList.add('is-revealing')};home.onpointermove=move;home.onpointerenter=move;home.onpointerleave=()=>{f.style.setProperty('--spot','0px');home.classList.remove('is-revealing')}}
async function loadModel(force=false){if(model&&!force)return model;if(modelPromise&&!force)return modelPromise;$('#modelError').hidden=true;modelPromise=(async()=>{try{if(!window.tmImage)throw Error('Model library unavailable');model=await tmImage.load(MODEL_URL+'model.json',MODEL_URL+'metadata.json');if(ready&&points.length)scheduleAnalysis();return model}catch(e){model=null;$('#modelError').hidden=false;throw e}finally{modelPromise=null}})();return modelPromise}
function shuffle(list){for(let i=list.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[list[i],list[j]]=[list[j],list[i]]}return list}
function choose(){let seen=[];try{seen=JSON.parse(localStorage.getItem(SEEN_KEY)||'[]')}catch(e){}if(seen.length>=ARCHIVE.length)seen=[];const lastCategory=norm(localStorage.getItem(LAST_CATEGORY_KEY)||'');let unseen=ARCHIVE.filter(x=>!seen.includes(x.id)&&x.id!==lastId),different=unseen.filter(x=>norm(x.category)!==lastCategory);if(!different.length&&unseen.length)different=unseen;if(!different.length){seen=[];unseen=ARCHIVE.filter(x=>x.id!==lastId);different=unseen.filter(x=>norm(x.category)!==lastCategory);if(!different.length)different=unseen}const categories=shuffle([...new Set(different.map(x=>norm(x.category)))]),nextCategory=categories[0],pool=different.filter(x=>norm(x.category)===nextCategory),selected=pool[Math.floor(Math.random()*pool.length)]||ARCHIVE[0];seen.push(selected.id);localStorage.setItem(SEEN_KEY,JSON.stringify(seen));localStorage.setItem(LAST_CATEGORY_KEY,selected.category||'');return selected}
async function loadArchive(){const button=$('#drawBtn');button.disabled=true;button.innerHTML='LOADING IMAGE LIBRARY <span>···</span>';try{const response=await fetch('archive/manifest.json');if(!response.ok)throw Error('Archive unavailable');ARCHIVE=(await response.json()).filter(x=>x.id&&x.src).map(x=>({...x,category:x.category||'Uncategorized'}))}catch(e){ARCHIVE=FALLBACK_ARCHIVE}button.disabled=false;button.innerHTML='DRAW AN IMAGE <span>↗</span>'}
function begin(){item=choose();lastId=item.id;sessionId=(crypto.randomUUID?.()||Date.now()+'-'+Math.random());ready=false;drawing=false;points=[];coverage=0;trace=[];predictions={};finalPrediction=null;$('#imageIndex').textContent=item.id.toUpperCase();$('#boardPrompt').textContent='LOADING IMAGE';$('#boardPrompt').classList.remove('hidden');$('#finishBtn').disabled=true;$('#visibleLabel').textContent='VISIBLE 0%';$('#progressFill').style.width='0%';$('#liveNote').textContent='The categories will move when enough visual evidence is available.';resetLabels();show('experiment');image=new Image();image.onload=()=>{ready=true;resize();draw();$('#boardPrompt').textContent=model?'DRAG TO ERASE':'WAITING FOR MODEL'};image.onerror=()=>$('#boardPrompt').textContent='IMAGE COULD NOT LOAD';image.src=item.src;loadModel().then(()=>{if(ready)$('#boardPrompt').textContent='DRAG TO ERASE'}).catch(()=>{})}
function resize(){const b=$('#imageBoard').getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);[canvas,mask,photo].forEach(c=>{c.width=Math.round(b.width*d);c.height=Math.round(b.height*d)});mctx.lineCap=mctx.lineJoin='round'}
function cover(){const cr=canvas.width/canvas.height,ir=image.naturalWidth/image.naturalHeight;if(ir>cr){const h=canvas.height,w=h*ir;return{x:(canvas.width-w)/2,y:0,w,h}}const w=canvas.width,h=w/ir;return{x:0,y:(canvas.height-h)/2,w,h}}
function draw(){if(!ready)return;const r=cover();pctx.clearRect(0,0,photo.width,photo.height);pctx.drawImage(image,r.x,r.y,r.w,r.h);pctx.globalCompositeOperation='destination-in';pctx.drawImage(mask,0,0);pctx.globalCompositeOperation='source-over';ctx.fillStyle='#ececeb';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(photo,0,0)}
function pos(e){const b=$('#imageBoard').getBoundingClientRect();return{x:(e.clientX-b.left)*canvas.width/b.width,y:(e.clientY-b.top)*canvas.height/b.height}}
function erasePoint(e){if(!ready)return;const q=pos(e),radius=Math.min(canvas.width,canvas.height)*.075;points.push({x:q.x,y:q.y,r:radius});mctx.fillStyle='#fff';mctx.beginPath();mctx.arc(q.x,q.y,radius,0,Math.PI*2);mctx.fill();draw();$('#boardPrompt').classList.add('hidden');updateCoverage();if(model)scheduleAnalysis();else $('#liveNote').textContent='Keep erasing. The model is still loading in the background.'}
function updateCoverage(){const data=mctx.getImageData(0,0,mask.width,mask.height).data;let visible=0,total=data.length/4;for(let i=3;i<data.length;i+=16)if(data[i]>20)visible++;coverage=Math.min(1,visible/(total/4));const pct=Math.round(coverage*100);$('#visibleLabel').textContent='VISIBLE '+pct+'%';$('#progressFill').style.width=pct+'%';$('#finishBtn').disabled=coverage<.12}
function scheduleAnalysis(){const wait=Math.max(0,320-(performance.now()-lastAnalyze));clearTimeout(analysisTimer);analysisTimer=setTimeout(runAnalysis,wait)}
function captureEvidence(){const r=cover(),out=document.createElement('canvas');out.width=photo.width;out.height=photo.height;const o=out.getContext('2d');o.drawImage(image,r.x,r.y,r.w,r.h);o.globalCompositeOperation='destination-in';o.drawImage(mask,0,0);const w=out.width,h=out.height,pixels=o.getImageData(0,0,w,h).data;let minX=w,minY=h,maxX=-1,maxY=-1;for(let y=0;y<h;y+=2)for(let x=0;x<w;x+=2)if(pixels[(y*w+x)*4+3]>12){minX=Math.min(minX,x);minY=Math.min(minY,y);maxX=Math.max(maxX,x);maxY=Math.max(maxY,y)}if(maxX<0)return out.toDataURL('image/png');const pad=Math.round(Math.min(w,h)*.025),sx=Math.max(0,minX-pad),sy=Math.max(0,minY-pad),sw=Math.min(w,maxX+pad)-sx,sh=Math.min(h,maxY+pad)-sy,crop=document.createElement('canvas'),scale=Math.min(1,680/Math.max(sw,sh));crop.width=Math.max(1,Math.round(sw*scale));crop.height=Math.max(1,Math.round(sh*scale));crop.getContext('2d').drawImage(out,sx,sy,sw,sh,0,0,crop.width,crop.height);return crop.toDataURL('image/png')}
async function runAnalysis(){if(!model||!ready)return;if(analyzing){pendingAnalysis=true;return}analyzing=true;lastAnalyze=performance.now();try{const list=[...await model.predict(canvas)].sort((a,b)=>b.probability-a.probability);predictions=Object.fromEntries(list.map(x=>[norm(x.className),x.probability]));finalPrediction=list[0];updateLabels();const top=norm(list[0].className),previous=trace.at(-1),changed=!previous||previous.key!==top,enoughChange=!previous||Math.abs(coverage-previous.coverage)>=.012;if(coverage>=.015&&changed&&enoughChange&&trace.length<12)trace.push({key:top,label:list[0].className,confidence:list[0].probability,coverage,scores:{...predictions},thumbnail:captureEvidence()})}catch(e){$('#modelError').hidden=false}finally{analyzing=false;if(pendingAnalysis){pendingAnalysis=false;scheduleAnalysis()}}}
function resetLabels(){Object.entries(LABELS).forEach(([key,cfg])=>{const el=$('#'+cfg.el);el.style.setProperty('--pull','0');el.style.setProperty('--scale','.82');el.style.setProperty('--opacity','.38');el.classList.remove('dominant');el.querySelector('b').textContent='0%';el.querySelector('p').textContent='';$('#'+cfg.line).style.opacity=.08})}
function updateLabels(){const board=$('#imageBoard'),w=board.clientWidth,h=board.clientHeight,center=[w/2,h/2],top=Object.entries(predictions).sort((a,b)=>b[1]-a[1])[0]?.[0];Object.entries(LABELS).forEach(([key,cfg])=>{const p=predictions[key]||0,el=$('#'+cfg.el),dominant=key===top,pull=Math.pow(p,.72),tx=(.5-cfg.anchor[0])*w*pull*.62,ty=(.5-cfg.anchor[1])*h*pull*.62;el.style.setProperty('--tx',tx.toFixed(1)+'px');el.style.setProperty('--ty',ty.toFixed(1)+'px');el.style.setProperty('--scale',(.78+pull*.52).toFixed(3));el.style.setProperty('--opacity',(.28+pull*.72).toFixed(3));el.classList.toggle('dominant',dominant);el.querySelector('b').textContent=Math.round(p*100)+'%';el.querySelector('p').textContent=dominant?DEFINITIONS[key]:'';const startX=cfg.anchor[0]*w+tx,startY=cfg.anchor[1]*h+ty,line=$('#'+cfg.line);line.setAttribute('x1',startX);line.setAttribute('y1',startY);line.setAttribute('x2',center[0]);line.setAttribute('y2',center[1]);line.style.opacity=(.08+p*.68).toFixed(2);line.style.strokeWidth=(.7+p*2.4).toFixed(2)});$('#liveNote').textContent=finalPrediction?'The strongest pull is currently '+finalPrediction.className+' at '+Math.round(finalPrediction.probability*100)+'%.':'Keep erasing to create more evidence.'}
function openDB(){return new Promise((resolve,reject)=>{const request=indexedDB.open(DB_NAME,DB_VERSION);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains(STORE_NAME)){const store=db.createObjectStore(STORE_NAME,{keyPath:'id'});store.createIndex('createdAt','createdAt');store.createIndex('label','label')}};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function evidencePutMany(records){if(!records.length)return;const db=await openDB();await new Promise((resolve,reject)=>{const tx=db.transaction(STORE_NAME,'readwrite'),store=tx.objectStore(STORE_NAME);records.forEach(x=>store.put(x));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close();await refreshEvidenceCount()}
async function evidenceAll(){const db=await openDB(),records=await new Promise((resolve,reject)=>{const q=db.transaction(STORE_NAME).objectStore(STORE_NAME).getAll();q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)});db.close();return records.sort((a,b)=>b.createdAt-a.createdAt)}
async function evidenceClear(){const db=await openDB();await new Promise((resolve,reject)=>{const tx=db.transaction(STORE_NAME,'readwrite');tx.objectStore(STORE_NAME).clear();tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close();await renderEvidence()}
async function refreshEvidenceCount(){try{const total=(await evidenceAll()).length;$('#archiveCount').textContent=total;$('#evidenceTotal').textContent=total+' FRAGMENT'+(total===1?'':'S')+' COLLECTED'}catch(e){$('#archiveCount').textContent='0'}}
async function saveTrace(){const createdAt=Date.now();await evidencePutMany(trace.map((x,i)=>({id:sessionId+'-'+i,sessionId,imageId:item.id,sourceCategory:item.category||'',sequence:i,label:x.label,key:x.key,confidence:x.confidence,coverage:x.coverage,scores:x.scores||{},thumbnail:x.thumbnail,createdAt:createdAt+i})))}
function complete(){if(!finalPrediction)return;saveTrace().catch(()=>{});$('#resultImage').src=item.src;$('#trace').innerHTML=trace.map((x,i)=>`<button class="trace-item" data-trace="${i}"><span class="trace-fragment"><img src="${x.thumbnail}" alt="All visual evidence available when the model predicted ${x.label}"></span><span>${String(i+1).padStart(2,'0')}</span><b>${x.label}</b><em>${Math.round(x.confidence*100)}% · ${Math.round(x.coverage*100)}% visible</em></button>`).join('<i>→</i>');document.querySelectorAll('.trace-item').forEach(button=>button.onclick=()=>selectTrace(Number(button.dataset.trace)));$('#finalReading').innerHTML=`<span>FINAL READING</span><h3>${finalPrediction.className}</h3><b>${Math.round(finalPrediction.probability*100)}%</b><p>${DEFINITIONS[norm(finalPrediction.className)]||''}</p><button id="viewFullResult" class="text-btn">VIEW COMPLETE SOURCE IMAGE ↗</button>`;$('#viewFullResult').onclick=()=>{document.querySelectorAll('.trace-item').forEach(x=>x.classList.remove('active'));$('#resultImage').src=item.src};show('result');if(trace.length)selectTrace(trace.length-1)}
