async function renderEvidence(){const records=await evidenceAll(),filtered=archiveFilter==='all'?records:records.filter(x=>x.key===archiveFilter);$('#evidenceGrid').innerHTML=filtered.map((x,i)=>`<article class="evidence-piece" style="--tilt:${((i%7)-3)*1.2}deg"><img src="${x.thumbnail}" alt="Partial visual evidence classified as ${x.label}"><div><b>${x.label}</b><span>${Math.round(x.confidence*100)}% · ${Math.round(x.coverage*100)}% VISIBLE</span><em>${x.imageId}</em></div></article>`).join('');$('#evidenceEmpty').hidden=records.length>0;$('#evidenceGrid').hidden=!filtered.length;$('#evidenceTotal').textContent=records.length+' FRAGMENT'+(records.length===1?'':'S')+' COLLECTED';$('#archiveCount').textContent=records.length}
