function resetSurface(){points=[];coverage=0;trace=[];predictions={};finalPrediction=null;mctx.clearRect(0,0,mask.width,mask.height);draw();resetLabels();$('#visibleLabel').textContent='VISIBLE 0%';$('#progressFill').style.width='0%';$('#finishBtn').disabled=true;$('#boardPrompt').textContent='DRAG TO ERASE';$('#boardPrompt').classList.remove('hidden');$('#liveNote').textContent='The categories will move when enough visual evidence is available.'}
const board=$('#imageBoard');board.onpointerdown=e=>{drawing=true;board.setPointerCapture(e.pointerId);erasePoint(e)};board.onpointermove=e=>{const b=board.getBoundingClientRect();$('#eraserCursor').style.left=(e.clientX-b.left)+'px';$('#eraserCursor').style.top=(e.clientY-b.top)+'px';board.classList.add('cursor-visible');if(drawing)erasePoint(e)};board.onpointerup=board.onpointercancel=()=>drawing=false;board.onpointerleave=()=>board.classList.remove('cursor-visible');
$('#drawBtn').onclick=begin;$('#tryAgainBtn').onclick=begin;$('#exitBtn').onclick=$('#resultExitBtn').onclick=$('#evidenceExitBtn').onclick=()=>show('intro');$('#archiveBtn').onclick=$('#viewArchiveBtn').onclick=openEvidence;$('#clearBtn').onclick=resetSurface;$('#finishBtn').onclick=complete;$('#retryBtn').onclick=()=>loadModel(true).then(()=>$('#modelError').hidden=true).catch(()=>{});$('#aboutBtn').onclick=()=>{const a=$('#aboutText');a.hidden=!a.hidden;$('#aboutBtn span').textContent=a.hidden?'＋':'−'};$('#clearEvidenceBtn').onclick=()=>{if(confirm('Clear all locally stored evidence fragments?'))evidenceClear()};$('#evidenceFilters').onclick=e=>{const button=e.target.closest('button[data-filter]');if(!button)return;archiveFilter=button.dataset.filter;document.querySelectorAll('#evidenceFilters button').forEach(x=>x.classList.toggle('active',x===button));renderEvidence()};
